SELECT
SEQ_HOSPITAL.NEXTVAL,(SELECT MEMBER_ID FROM APP_MEMBER WHERE LOGIN_ID = 'test001'),'마포온 동물메디컬센터','서울특별시 마포구 마포대로 173-14 마포 센텀 슬로우스퀘어 308~310호 (아현동)','서울특별시 마포구 아현동 618-19 마포 센텀 슬로우스퀘어','0507-1319-3535',195829.955210361,449860.57540675,'10:00','19:30','CLOSED','마포온 동물메디컬센터는 수술 및 중증질환 중심의 2차 동물병원입니다. 보호자분들이 어려운 치료 선택 과정에서 보다 합리적인 결정을 내릴 수 있도록 정확한 진단과 충분한 설명을 제공합니다. 중환자 심혈관계질환 호르몬질환 정형외과 신경외과 연부조직외과 진료를 기반으로 체계적인 진단과 치료 시스템을 운영합니다. 치료 과정과 예후를 보호자분들께 이해하기 쉽게 안내하며 환자와 보호자 모두가 안심할 수 있는 진료 환경을 만들어가겠습니다. 현재 2026년 7월1일 개원예정이며 지역사회와 오래 함께할 수 있는 신뢰 기반의 동물메디컬센터를 지향합니다.','/images/hospital/1.jpg',TIMESTAMP '2026-07-23 05:58:35.099901',NULL,'https://www.instagram.com/mapoonamc','마포구','1','영업/정상','2026-06-26 18:15:41','2026-06-27 22:02:51','13:00-14:00',NULL,'2','피부과/내과/안과/치과/임상병리학과/영상의학과/예방의학과/이비인후과/비뇨기과/외과/정형외과/산과','소재원','https://www.instagram.com/mapoonamc','2026-07-08',NULL
FROM DUAL;

