SEQ_HOSPITAL.NEXTVAL,(SELECT MEMBER_ID FROM APP_MEMBER WHERE LOGIN_ID = 'test069'),'다봄 동물병원','서울특별시 광진구 자양로 163 우남빌딩 (구의동)','서울특별시 광진구 구의동 254-36 우남빌딩 1층','02-456-7775',207334.35237407,448890.470998334,'10:00','19:30','OPEN','안녕하세요. 24년 광진구 구의동에 신규개원한 다봄동물병원입니다. 저희 병원은 개 고양이 진료 뿐만 아니라 토끼 고슴도치 도마뱀 거북 등의 특수동물 진료가 가능합니다. 특수동물 질병 뿐만 아니라 일반적 사육 영양 관리 등 문의사항이 있으시면 언제든 전화주세요~','/images/hospital/69.jpg',TIMESTAMP '2026-07-23 05:59:06.712155',NULL,'https://www.instagram.com/dabom_ah','광진구','1','영업/정상','2024-07-29 16:10:15','2026-05-08 22:46:01','13:00-14:00','일요일','피부과/내과/안과/치과/예방의학과/이비인후과/비뇨기과/외과/정형외과/산과','피부과/내과/안과/치과/예방의학과/이비인후과/비뇨기과/외과/정형외과/산과',NULL,'https://www.instagram.com/dabom_ah','2026-07-08',NULL
FROM DUAL;

