INSERT INTO HOSPITAL (HOSPITAL_ID,OWNER_ID,NAME,ADDRESS,DETAIL_ADDRESS,PHONE,LATITUDE,LONGITUDE,OPEN_TIME,CLOSE_TIME,STATUS,DESCRIPTION,IMAGE_URL,CREATED_AT,UPDATED_AT,WEBSITE_URL,DISTRICT,STATUS_CODE,OPERATION_STATUS_TEXT,DATA_UPDATED_AT,LAST_MODIFIED_AT,BREAK_TIME,CLOSED_DAYS,MEDICAL_SUBJECTS,DOCTOR_INFO,OWNER_NAME,SOURCE_URL,CHECKED_AT,NOTE)
SELECT
SEQ_HOSPITAL.NEXTVAL,(SELECT MEMBER_ID FROM APP_MEMBER WHERE LOGIN_ID = 'test086'),'24시 딜라이트 동물의료센터','서울특별시 도봉구 도봉로 578 2층 2호 (창동)','서울특별시 도봉구 창동 715-1','02-904-1004',203439.44750178,461539.552727474,'00:00','24:00','OPEN','언제나 반려동물을 사랑으로 맞이하겠습니다:) <소개> -도봉구 최대규모의 동물병원(200평 규모) -진료시간 365일 24시간 연중무휴 -수도권 동물병원 최초 TOSHIBA사 128 CT 도입 및 운영 -각 과별 분과 진료(다년간 대학병원 내과 외과 영상의학과 수련 전문의료진) ※예약 후 방문하시면 대기 없이 진료 가능하니 참고하시어 내원 하시길 바랍니다※ 1.응급 중환자센터운영(365일 24시간 수의사 상주 및 응급 수술 가능) 2.수술전문병원(수술실 수술 준비실 별도 구분 및 대학 병원급 수술 장비 보유) 3.고양이 특화진료(고양이 전용 대기실 진료실 입원실 구분/ ISFM 고양이 친화병원 등급 중 최고 레벨인 골드 등급 인증 획득) 4.건강검진센터 재활센터 운영(수중러닝머신 P1 레이저) *수중 러닝머신 재활 후 편의를 위하여 드라이룸이 마련되어 있습니다. 5.스케일링 전문센터 운영 (반려동물 전용 치과베드에서 진행되는 덴탈토탈케어가 진행됩니다. 치과 전용 수술실을 독립 운영하고 있습니다.) <주 차 안 내> 병원 주차장은 건물 뒷편에 넓게 마련되어 있습니다','/images/hospital/86.jpg',TIMESTAMP '2026-07-23 05:59:07.428305',NULL,'http://delightamc.com/','도봉구','1','영업/정상','2025-11-19 16:24:43','2026-05-09 22:02:15',NULL,NULL,'2','외과/내과/치과/정형외과','구현성','http://delightamc.com/','2026-07-08','고양이특화병원'
FROM DUAL;

